"import express from 'express';
import cors from 'cors';
import { PrismaClient } from '@prisma/client';

const app = express();
const prisma = new PrismaClient();
const PORT = process.env.PORT || 3001;

app.use(cors());
app.use(express.json());

// Get all allocations
app.get('/api/allocations', async (req, res) => {
  try {
    const allocations = await prisma.fundAllocation.findMany({
      include: {
        expenditures: true
      }
    });

    // Map data to include dynamic calculations
    const result = allocations.map(allocation => {
      const expended = allocation.expenditures.reduce((sum, exp) => sum + exp.amount, 0);
      const balance = allocation.allocatedAmount - expended;
      const utilization = allocation.allocatedAmount > 0 
        ? Math.round((expended / allocation.allocatedAmount) * 100)
        : 0;

      return {
        id: allocation.id,
        fundType: allocation.fundType,
        allocatedAmount: allocation.allocatedAmount,
        expended,
        balance,
        utilization,
        status: allocation.status
      };
    });

    res.json(result);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch allocations' });
  }
});

// Add new allocation
app.post('/api/allocations', async (req, res) => {
  try {
    const { fundType, allocatedAmount, status } = req.body;
    const newAllocation = await prisma.fundAllocation.create({
      data: {
        fundType,
        allocatedAmount: parseFloat(allocatedAmount),
        status: status || 'Pending'
      }
    });
    res.status(201).json(newAllocation);
  } catch (error) {
    res.status(500).json({ error: 'Failed to create allocation' });
  }
});

